def transform(grid):
    h, w = len(grid), len(grid[0])
    full = [r for r in range(h) if len(set(grid[r])) == 1]
    if not full:
        return [row[:] for row in grid]

    color = grid[full[0]][0]
    out = [row[:] for row in grid]

    # Recolor the full horizontal separator rows.
    for r in full:
        for c in range(w):
            out[r][c] = 2

    # Recolor uninterrupted vertical runs of the separator color that
    # extend from an outer edge to a horizontal separator.
    for c in range(w):
        for r in range(h):
            if grid[r][c] != color:
                continue
            top_edge = all(grid[k][c] == color for k in range(r + 1))
            bottom_edge = all(grid[k][c] == color for k in range(r, h))
            if top_edge or bottom_edge:
                for k in range(h):
                    if grid[k][c] == color:
                        out[k][c] = 2
    return out
